package com.itemoptionhider;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(ItemOptionHiderConfig.GROUP)
public interface ItemOptionHiderConfig extends Config
{
	String GROUP = "itemoptionhider";

	@ConfigItem(
		keyName = "hides",
		name = "Hidden item options",
		description = "One rule per line, formatted as option,item name. * matches any text. Lines starting with # are ignored. Hidden options are removed from both left click and the right click menu.",
		position = 0
	)
	default String hides()
	{
		return "# One rule per line: option,item name (* is a wildcard)\n"
			+ "# Examples:\n"
			+ "# combine,torn clue scroll*\n"
			+ "# use,torn clue scroll*\n"
			+ "# use,* -> torn clue scroll*\n";
	}
}

package com.itemoptionhider;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.PostMenuSort;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Item Option Hider",
	description = "Hide specific menu options on specific items, using an option,item list",
	tags = {"menu", "entry", "hide", "item", "option", "misclick"}
)
public class ItemOptionHiderPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ItemOptionHiderConfig config;

	private final List<HideRule> rules = new ArrayList<>();

	@Provides
	ItemOptionHiderConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ItemOptionHiderConfig.class);
	}

	@Override
	protected void startUp()
	{
		parseRules();
	}

	@Override
	protected void shutDown()
	{
		rules.clear();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ItemOptionHiderConfig.GROUP.equals(event.getGroup()))
		{
			parseRules();
		}
	}

	@Subscribe
	public void onPostMenuSort(PostMenuSort event)
	{
		if (rules.isEmpty())
		{
			return;
		}

		MenuEntry[] entries = client.getMenuEntries();
		List<MenuEntry> kept = new ArrayList<>(entries.length);
		boolean changed = false;

		for (MenuEntry entry : entries)
		{
			if (shouldHide(entry))
			{
				changed = true;
			}
			else
			{
				kept.add(entry);
			}
		}

		if (changed)
		{
			client.setMenuEntries(kept.toArray(new MenuEntry[0]));
		}
	}

	private boolean shouldHide(MenuEntry entry)
	{
		// Only ever touch menu entries that belong to an item. This keeps the
		// plugin away from entries on players, NPCs, spells, and objects.
		if (entry.getItemId() <= -1)
		{
			return false;
		}

		final String option = Text.removeTags(entry.getOption()).trim();
		final String target = Text.removeTags(entry.getTarget()).trim();

		for (HideRule rule : rules)
		{
			if (rule.option.matcher(option).matches() && rule.target.matcher(target).matches())
			{
				return true;
			}
		}
		return false;
	}

	private void parseRules()
	{
		rules.clear();
		for (String line : config.hides().split("\\R"))
		{
			line = line.trim();
			if (line.isEmpty() || line.startsWith("#"))
			{
				continue;
			}

			final int comma = line.indexOf(',');
			final String option = comma < 0 ? line : line.substring(0, comma);
			final String target = comma < 0 ? "" : line.substring(comma + 1);
			rules.add(new HideRule(glob(option), glob(target)));
		}
	}

	private static Pattern glob(String s)
	{
		final StringBuilder sb = new StringBuilder();
		for (String part : s.trim().split("\\*", -1))
		{
			if (sb.length() > 0)
			{
				sb.append(".*");
			}
			sb.append(Pattern.quote(part));
		}
		return Pattern.compile(sb.toString(), Pattern.CASE_INSENSITIVE);
	}

	private static class HideRule
	{
		private final Pattern option;
		private final Pattern target;

		private HideRule(Pattern option, Pattern target)
		{
			this.option = option;
			this.target = target;
		}
	}
}

package com.itemoptionhider;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ItemOptionHiderPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ItemOptionHiderPlugin.class);
		RuneLite.main(args);
	}
}
